import itertools

def get_digits(n):
    return [int(d) for d in str(n)]

def is_distinct_nonzero(n):
    s = str(n)
    if '0' in s or len(set(s)) != len(s):
        return False
    return True

# Memoization cache for 'is_good' checks
good_cache = {}

def is_good(m):
    if m in good_cache:
        return good_cache[m]

    # 1. Constraint check: Distinct nonzero digits
    if not is_distinct_nonzero(m):
        return False

    # 2. Base Case
    if m < 10:
        return True

    # 3. Recursive Step: Check all possible single-digit removals
    digits = get_digits(m)
    L = len(digits)

    for i in range(L):
        # Construct m' by removing the digit at index i
        m_prime_list = digits[:i] + digits[i+1:]
        m_prime = int("".join(map(str, m_prime_list)))

        # Check 1: m' must divide m
        if m % m_prime == 0:
            # Check 2: m' must be a good number
            if is_good(m_prime):
                good_cache[m] = True
                return True

    good_cache[m] = False
    return False

# --- Brute Force Search ---
# We start from the largest possible 4-digit number with distinct nonzero digits: 9876
# We search downwards until we find the first good number.
max_digits = 4
start_number = 9876

print(f"Starting exhaustive search for largest good number with {max_digits} distinct nonzero digits...")

found_largest = None
for m in range(start_number, 999, -1):
    if not is_distinct_nonzero(m):
        continue

    if is_good(m):
        found_largest = m
        break

if found_largest:
    print(f"Largest good number found: {found_largest}")
else:
    print("No good number found in the search range.")
